  async printMail(mail: IMail, i: number): Promise<void> {
    logger.info(`mail ${i}`, await mail.getFrom());
    const subject = await mail.getSubject();
    const html = await mail.getHtml();
    const plain = await mail.getPlain();
    const date = await mail.getDate();
    const attachments = await mail.getAttachments();
    const inlines = await mail.getInlines();
    const as: IBuffer[] = [];
    const names: string[] = [];
    for (const attach of attachments) {
      /*
      const a = await attach.getBody();
      as.push(a);
      await this.saveFile(attach.getFileName(), a);
      */
      names.push(attach.getFileName());
    }
    for (const inline of inlines) {
      /*
      const a = await inline.getBody();
      as.push(a);
      await this.saveFile(inline.getFileName(), a);
      */
      names.push(inline.getFileName());
    }
    const d = [
      await mail.getFrom(),
      await mail.getTo(),
      await mail.getCc(),
      await mail.getBcc(),
      await mail.getPriority(),
      await mail.isSeen(),
      await mail.isFlagged(),
      await mail.isAnswered(),
      await mail.getSize(),
      await mail.getMessageId()
    ]
    // await mail.setFlagged(true);
    // const isSeen = await mail.isSeen();
    const headers = await mail.getAllHeaders();
    logger.info("html--- ", i, '--', mail.getId(), '--', subject, '---', html.substring(0, 100), date.toUTCString());
    logger.info("html--- ", JSON.stringify(d), JSON.stringify(names), as.length);
    logger.info("html--- ", plain);
    logger.info("html--- ", headers);
    return;
    const raw = await mail.getRaw();
    const s = await raw.readAll();
    logger.info('html-- ', s);
  }

