  async testTaskQueue(): Promise<void> {
    const q = new TaskQueue();
    const f1 = (async () => {
      logger.info("task 1");
      const task = await q.wait();
      logger.info("task 1 begin");
      await delay(1000);
      task.finish();
      logger.info("task 1 end");
    })();
    const f2 = (async () => {
      logger.info("task 2");
      await delay(100);
      const task = await q.wait();
      logger.info("task 2 begin");
      task.finish();
      logger.info("task 2 end");
    })();
    const f3 = (async () => {
      logger.info("task 3");
      const task = await q.wait();
      logger.info("task 3 begin");
      await delay(1100);
      task.finish();
      logger.info("task 3 end");
    })();
    const doWork = async (i: number, timeout: number) => {
      logger.info(`task ${i} begin`);
      if (timeout) {
        await delay(timeout);
      }
      logger.info(`task ${i} end`);
    }
    const f4 = q.doTask(async () => {
      logger.info("task 4");
      await doWork(4, 100);
      return 'aaa'
    })
    const f5 = q.doTask(() => {
      logger.info("task 5");
      doWork(5, 0);
      return 123
    })
    const res = await Promise.all([f1, f2, f3, f4, f5])
    logger.info(res);
  }
